import"./chunk-ZW5NV4UO.js";var e={en:{title:"Math on Mastodon: people and hashtags to follow",description:"Build a math feed on Mastodon: research, teaching, puzzles and mathematical art. Choose people and hashtags, then preview their public posts.",heading:"Math on Mastodon",listTitle:"Mathematics",intro:["A neat proof, a puzzle to think about, a picture that makes an idea click: there are many ways into mathematics. This starter kit looks across research, teaching and recreational math.","Choose the people and hashtags that interest you, then try the preview. You can explore public posts before signing in and adjust your choices before following."],faq:[{q:"Do I need an account?",a:"You can browse the recommendations and preview public posts without an account. To follow people and hashtags or create a Mastodon list, sign in with your Mastodon account."},{q:"Is this only for professional mathematicians?",a:"No. Teaching, puzzles, mathematical art and explanations belong alongside research. Some posts assume specialist knowledge; preview the people and tags to find the mix you enjoy."},{q:"How do I get onto this list?",a:"Share mathematical posts regularly and allow your server to suggest your profile. Recommendations depend on recent activity, topic fit and review. For help or removal, contact @mawkingbird@mastodon.social."}]},de:{title:"Mathematik auf Mastodon: Menschen und Hashtags finden",description:"Forschung, Unterricht, Knobeleien und mathematische Kunst auf Mastodon. W\xE4hle Menschen und Hashtags f\xFCr deinen Feed und probiere die Vorschau aus.",heading:"Mathematik auf Mastodon",listTitle:"Mathematik",intro:["Ein eleganter Beweis, eine knifflige Aufgabe oder eine Zeichnung, die den Groschen fallen l\xE4sst: Mathematik hat viele Zug\xE4nge. Hier geht es um Forschung, Unterricht und die Freude am Knobeln.","Such dir Menschen und Hashtags aus und schau in die Vorschau. \xD6ffentliche Beitr\xE4ge kannst du ohne Anmeldung lesen; wem du folgen m\xF6chtest, entscheidest du danach."],faq:[{q:"Brauche ich ein Konto?",a:"Die Empfehlungen und die Vorschau \xF6ffentlicher Beitr\xE4ge kannst du ohne Konto ansehen. Um Menschen und Hashtags zu folgen oder eine Mastodon-Liste anzulegen, meldest du dich mit deinem Mastodon-Konto an."},{q:"Muss ich Mathematik studiert haben?",a:"Nein. Unterrichtsideen, R\xE4tsel, mathematische Kunst und Erkl\xE4rungen geh\xF6ren ebenso dazu wie Forschung. Manche Beitr\xE4ge setzen Fachwissen voraus. Mit der Vorschau findest du heraus, was dich anspricht."},{q:"Wie komme ich auf diese Liste?",a:"Schreib regelm\xE4\xDFig \xFCber Mathematik und erlaube deinem Server, dein Profil vorzuschlagen. Auch aktuelle Aktivit\xE4t, Themenbezug und die Pr\xFCfung z\xE4hlen. Bei Fragen oder f\xFCr eine Entfernung erreichst du @mawkingbird@mastodon.social."}]},fr:{title:"Math\xE9matiques sur Mastodon\xA0: comptes et hashtags \xE0 suivre",description:"Recherche, enseignement, \xE9nigmes et art math\xE9matique sur Mastodon. Choisis des comptes et des hashtags, puis essaie l\u2019aper\xE7u de ton fil.",heading:"Les math\xE9matiques sur Mastodon",listTitle:"Math\xE9matiques",intro:["Une preuve astucieuse, une \xE9nigme qui r\xE9siste, un dessin qui \xE9claire une notion\xA0: les maths se partagent de bien des fa\xE7ons. Cette s\xE9lection fait place \xE0 la recherche, \xE0 l\u2019enseignement et aux maths r\xE9cr\xE9atives.","Choisis les comptes et les hashtags qui t\u2019int\xE9ressent, puis regarde l\u2019aper\xE7u. Tu peux lire les publications publiques sans te connecter et affiner tes choix avant de t\u2019abonner."],faq:[{q:"Faut-il un compte\u202F?",a:"Non pour parcourir les recommandations et l\u2019aper\xE7u des publications publiques. Pour suivre des comptes et des hashtags ou cr\xE9er une liste Mastodon, connecte-toi avec ton compte Mastodon."},{q:"Faut-il faire de la recherche en maths\u202F?",a:"Non. Les \xE9nigmes, les explications, l\u2019enseignement et l\u2019art math\xE9matique ont aussi leur place. Certains \xE9changes demandent des connaissances sp\xE9cialis\xE9es\xA0; l\u2019aper\xE7u t\u2019aide \xE0 trouver ce qui te pla\xEEt."},{q:"Comment appara\xEEtre sur cette liste\u202F?",a:"Publie r\xE9guli\xE8rement sur les math\xE9matiques et autorise ton serveur \xE0 sugg\xE9rer ton profil. L\u2019activit\xE9 r\xE9cente, le lien avec le sujet et la v\xE9rification comptent aussi. Pour une question ou un retrait, contacte @mawkingbird@mastodon.social."}]}};export{e as COPY};
